inline float clampF(float x){  double zero = 0.0, maxf = 1.0;  double _x;    /* Use doubles to prevent compiler from using frsp all     over the place.  Note the careful use of 255.0f so     that the compiler generates a single precision multiply. */  _x = x;  _x = __fsel(_x,_x,zero);  _x = __fsel(maxf - _x, _x, maxf);  return (float)_x;}#pragma mark -                       /*________________________________________________________________________________________      glrReadPixels________________________________________________________________________________________*/// values for endian mode#define EM_SWAP_BYTES 0#define EM_SWAP_SHORTS 1#define EM_NO_SWAP 2inline void _h3ReadDepthPixelsGeneric(	GLint endian_mode,			// must be a constant	GLint output_type,			// must be a constant	GLint inX, 	GLint inY, 	GLsizei inWidth, 	GLsizei inHeight, 	GLsizei buffHeight,	FxU32 stride,	FxU8 *depthBuffer, 	GLvoid *outPixels, 	GLint out_row_bytes,	GLfloat depth_bias, 	GLfloat depth_scale){	FxU32 x, y;	FxU16 depthPixel, *rowPixels;	FxFloat depthFloat;	void * outRow;		for(y = 0; y < inHeight; y++) {		outRow = ((FxU8 *)outPixels + y * out_row_bytes);				rowPixels = (FxU16 *)(depthBuffer + stride * (buffHeight - y - inY - 1) + inX * sizeof(FxU16));		for(x = 0; x < inWidth; x++) {			switch(endian_mode){			case EM_SWAP_BYTES:				depthPixel = __lhbrx(&rowPixels[x],0);				break;			case EM_NO_SWAP:				depthPixel = rowPixels[x];				break;			case EM_SWAP_SHORTS:				// to do: verify that this is correct if inX is odd      			depthPixel = rowPixels[x ^ 1];				break;			}			depthFloat = ((FxFloat)depthPixel) * (1.0f / 65535.0f);			depthFloat = depthFloat * depth_scale + depth_bias;			if(depthFloat < 0.0f) depthFloat = 0.0f;			if(depthFloat > 1.0f) depthFloat = 1.0f;			switch(output_type){			case GL_BYTE:				((GLbyte *)outRow)[x] = depthFloat * (GLuint)0x0000007f;				break;			case GL_UNSIGNED_BYTE:				((GLubyte *)outRo